//! 📖️ Individually authored persisted Playbook document and its typed `flow` child address.
use super::PlaybookSnapshot;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::{SqliteDatabase,SqliteSnapshotControl,SqliteSnapshotPhase,SnapshotEncoding,validate_sqlite_database_schema,artifact::{Cell,Projection,Reconstruction}}};
use semio_framework_value::{ValueError,ValueRefusalKind};
fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}

impl ArtifactSqliteSnapshot for PlaybookSnapshot{
 const SQLITE_SCHEMA:&'static str=include_str!("🗄️.sql");
 fn decode_sqlite_snapshot_native(payload:&store::os_io::IoPayload,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{if Self::SQLITE_SCHEMA.len()>c.limits().max_schema_bytes{return Err(invalid("Playbook authored SQL exceeds schema byte limit"))}c.check_rows(2)?;store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),super::PlaybookPackRecord::__dsl_spec_producer(),|record,control|super::PlaybookPackRecord::__dsl_from_record_controlled(record,control).map(super::PlaybookPackRecord::into_snapshot),c)}
 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,c:&mut SqliteSnapshotControl<'_>)->Result<store::os_io::IoPayload,ValueError>{if Self::SQLITE_SCHEMA.len()>c.limits().max_schema_bytes{return Err(invalid("Playbook authored SQL exceeds schema byte limit"))}c.check_rows(2)?;let record=super::PlaybookPackRecord::from_snapshot(self);store::encode_sqlite_snapshot_record_native(encoding,<Self as store::ArtifactDsl>::envelope_id(),super::PlaybookPackRecord::__dsl_spec_producer(),|control|record.__dsl_to_record_controlled(control),c)}
 fn to_sqlite_database(&self,c:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut p=Projection::new(Self::SQLITE_SCHEMA,c)?;p.check_rows(2)?;p.insert("playbook_document",&[Cell::Text(&self.schema),Cell::Text(&self.id),Cell::Text(&self.version),self.title.as_deref().map(Cell::Text).unwrap_or(Cell::Null)])?;let f=&self.flow;let ft=&f.target;let fd=&ft.dialect;p.insert("playbook_flow_child",&[Cell::Text(&f.child_id),Cell::Text(&ft.artifact_id),Cell::Text(&fd.artifact_kind),Cell::Text(&fd.standard),Cell::Text(&fd.subset)])?;p.finish()}
 fn from_sqlite_database(d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{validate_sqlite_database_schema(d,Self::SQLITE_SCHEMA,c.limits())?;c.check_database(d,SqliteSnapshotPhase::ReconstructSnapshot)?;let p=d.table("playbook_document")?.single_row()?;let f=d.table("playbook_flow_child")?.single_row()?;if p.rowid!=1||f.rowid!=1||p.integer(0)?!=1||f.integer(0)?!=1||p.values.len()!=5||f.values.len()!=6{return Err(invalid("Playbook requires exact identity-1 parent and child rows"))}let mut r=Reconstruction::new(c)?;let schema=r.text(p.text(1)?)?;let id=r.text(p.text(2)?)?;let version=r.text(p.text(3)?)?;let title=p.optional_text(4)?.map(|s|r.text(s)).transpose()?;let flow=store::ArtifactChild::new(r.text(f.text(1)?)?,store::os_io::ArtifactRef{artifact_id:r.text(f.text(2)?)?,dialect:store::os_io::ArtifactDialect{artifact_kind:r.text(f.text(3)?)?,standard:r.text(f.text(4)?)?,subset:r.text(f.text(5)?)?}});r.checkpoint()?;Ok(Self{schema,id,version,title,flow})}
 fn validate_sqlite_snapshot_subset(&self,dialect:&store::os_io::ArtifactDialect,d:&SqliteDatabase,c:&mut SqliteSnapshotControl<'_>)->store::io_schema::IoResult<()>{c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,0,1).map_err(store::io_schema::IoError::from_value_error)?;if dialect.artifact_kind!="s.playbook.playbook"||dialect.standard!="1"||dialect.subset!="*"{return Err(store::io_schema::IoError::from_value_error(invalid("Playbook dialect differs from its owned wildcard")))}if d.table("playbook_document").map_err(store::io_schema::IoError::from_value_error)?.single_row().map_err(store::io_schema::IoError::from_value_error)?.text(1).map_err(store::io_schema::IoError::from_value_error)?!=self.schema{return Err(store::io_schema::IoError::from_value_error(invalid("Playbook projected schema differs")))}c.checkpoint(SqliteSnapshotPhase::ProjectSnapshot,1,1).map_err(store::io_schema::IoError::from_value_error)?;Ok(store::io_schema::IoOutcome::clean(()))}
}
